"""
    Calculate N-wave overpressure amplitude

    Parameters
    ----------
    M -- Mach number
    bulletDiam -- bullet diameter in m
    bulletLen -- bullet length in m
    xmiss -- miss distance in m
    patm -- atmosperic pressure in Pa

    Returns
    -------
    pmax -- N-wave overpressure amplitude in Pa
    """
def nWaveAmplitude(
    M: Any, bulletDiam: Any, bulletLen: Any, xmiss: Any, patm: Any = 101000.0
) -> object {
    pmax = (
        (0.53 * patm * bulletDiam * (((M ** 2) - 1) ** 0.125))
        / ((xmiss ** 0.75) * (bulletLen ** 0.25))
    );
    return pmax;
}

"""
    This function caculates the longuest sub array in a list

    A sub array is an array which doesn't contain any 0

    It returns the index of the last element which composes the sub array
    and the length of the sub array
    """
def longuest_sub_array(arr: Any) -> object {
    sub_arrays = [];
    last_index = 0;
    length = 0;
    for (i, l) in enumerate(arr) {
        if (l != 0) {
            length += 1;
            last_index = i;
        } else {
            if (last_index == (i - 1)) {
                sub_arrays.append((last_index, length));
            }
            length = 0;
        }
    }
    if (sub_arrays == [(0, 0)]) {
        print('The image cannot be cropped vertically');
        return None;
    }
    return max(sub_arrays, key=lambda (p: Any) { p[1]; });
}

